#!/bin/sh
# Optional helper for the guided installation. Acta does not need it: `docker compose up`
# with or without a .env file still works exactly as before (see docs/SELF-HOSTING.md).
#
#   scripts/install.sh                         local evaluation on http://localhost:4317
#   scripts/install.sh --origin https://acta.example.org [--port 4317]
#
# It checks Docker, writes a minimal .env ONLY when none exists and options were given,
# starts the services, and prints the address (with the one-time setup code) of the
# first-run wizard. Secrets are generated by the containers into private volumes; this
# script never sees or prints them. Running it again changes nothing that already exists.
set -eu

origin=""
port=""
while [ $# -gt 0 ]; do
  case "$1" in
    --origin) origin="${2:-}"; shift 2 ;;
    --port) port="${2:-}"; shift 2 ;;
    -h | --help)
      sed -n '2,10p' "$0" | sed 's/^# \{0,1\}//'
      exit 0
      ;;
    *) echo "Opción desconocida: $1 (usa --help)" >&2; exit 2 ;;
  esac
done

cd "$(dirname "$0")/.."

fail() { echo "Error: $*" >&2; exit 1; }

command -v docker >/dev/null 2>&1 || fail "Docker no está instalado."
docker info >/dev/null 2>&1 || fail "Docker no responde. Inícialo e inténtalo de nuevo."
version="$(docker compose version --short 2>/dev/null || true)"
[ -n "$version" ] || fail "Se requiere Docker Compose v2 (plugin 'docker compose')."
numeric="$(printf '%s' "$version" | sed 's/^v//' | sed 's/[^0-9.].*$//')"
major="$(printf '%s' "$numeric" | cut -d. -f1)"
minor="$(printf '%s' "$numeric" | cut -d. -f2)"
patch="$(printf '%s' "$numeric" | cut -d. -f3)"
if [ "${major:-0}" -lt 2 ] ||
  { [ "${major:-0}" -eq 2 ] && [ "${minor:-0}" -lt 24 ]; } ||
  { [ "${major:-0}" -eq 2 ] && [ "${minor:-0}" -eq 24 ] && [ "${patch:-0}" -lt 4 ]; }; then
  fail "Se requiere Docker Compose 2.24.4 o posterior (encontrado: $version)."
fi

if [ -n "$origin" ] || [ -n "$port" ]; then
  [ ! -e .env ] || fail "Ya existe un archivo .env y no lo modifico. Ajusta ahí APP_ORIGIN, COOKIE_SECURE, NODE_ENV y APP_PORT, o bórralo tú si quieres empezar de cero."
  if [ -n "$origin" ]; then
    case "$origin" in
      https://*) secure=true; mode=production ;;
      http://localhost | http://localhost:* | http://127.0.0.1 | http://127.0.0.1:*)
        secure=false; mode=development ;;
      *) fail "--origin debe ser una dirección https:// (o http://localhost para pruebas locales)." ;;
    esac
    case "$origin" in *[!A-Za-z0-9:/._-]*) fail "--origin contiene caracteres no permitidos." ;; esac
  else
    origin="http://localhost:${port}"; secure=false; mode=development
  fi
  if [ -n "$port" ]; then
    case "$port" in '' | *[!0-9]*) fail "--port debe ser un número." ;; esac
  fi
  umask 077
  {
    echo "# Generado por scripts/install.sh. Puedes editarlo o borrarlo; Acta no lo necesita para funcionar."
    echo "APP_ORIGIN=$origin"
    echo "COOKIE_SECURE=$secure"
    echo "NODE_ENV=$mode"
    [ -z "$port" ] || echo "APP_PORT=$port"
  } > .env
  echo "Se creó .env con la dirección de la instalación."
fi

echo "Iniciando Acta (la primera vez descarga y construye las imágenes; puede tardar varios minutos)…"
docker compose up --build -d --wait

errors="$(mktemp)"
if address="$(docker compose exec -T backend node scripts/setup-token.mjs --url 2>"$errors")"; then
  rm -f "$errors"
  echo
  echo "Acta está lista. Para crear al administrador y configurar la institución abre:"
  echo
  echo "  $address"
  echo
  echo "El código del enlace es de un solo uso y caduca en 2 horas. Si caduca: docker compose exec backend node scripts/setup-token.mjs"
else
  reason="$(cat "$errors" 2>/dev/null || true)"
  rm -f "$errors"
  echo
  case "$reason" in
    Setup:*) echo "Acta está en marcha. ${reason#Setup: }" ;;
    *) echo "Acta está en marcha, pero no se pudo emitir el código de instalación. Ejecuta: docker compose exec backend node scripts/setup-token.mjs" ;;
  esac
fi
